CREATE OR REPLACE FUNCTION public.set_original_deletion(p_user uuid,p_file uuid,p_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.files; BEGIN SELECT * INTO f FROM public.files WHERE id=p_file AND user_id=p_user FOR UPDATE; IF f.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=f.workspace_id AND user_id=p_user) OR p_state NOT IN ('Deleting','Deleted','Uploaded') THEN RAISE EXCEPTION 'Unauthorized deletion'; END IF; IF f.status='Deleted' THEN RETURN; END IF; UPDATE public.files SET status=p_state WHERE id=p_file; IF p_state='Deleted' THEN INSERT INTO public.activity_logs(workspace_id,user_id,file_id,file_name,action) VALUES(f.workspace_id,p_user,f.id,f.name,'File deleted'); END IF; END $$;
REVOKE ALL ON FUNCTION public.set_original_deletion(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_original_deletion(uuid,uuid,text) TO service_role;
COMMENT ON FUNCTION public.set_original_deletion(uuid,uuid,text) IS 'Authenticated owner-confirmed storage removal; preserve metadata and audit, exclude deleted originals from active inventory.';